/* Keep historical item keys compatible while presenting the current terminology. */
(()=>{
 const legacy='不良品',current='製程報廢';
 const normalize=value=>typeof value==='string'?value.replaceAll(legacy,current):Array.isArray(value)?value.map(normalize):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).map(([k,v])=>[k,normalize(v)])):value;
 const stored=value=>Array.isArray(value)?value.map(stored):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).map(([k,v])=>[k,k==='item'&&v===current?legacy:stored(v)])):value;
 const original=api;api=async function(payload){const result=normalize(await original(String(payload?.action||'').startsWith('scrap_')?stored(payload):payload));if(payload?.action==='scrap_get'){if(Array.isArray(result.items)&&!result.items.includes('S10設備製程報廢'))result.items.push('S10設備製程報廢');if(result.record?.quotes&&!result.record.quotes.some(q=>q.item==='S10設備製程報廢'))result.record.quotes.push({item:'S10設備製程報廢',price:null});}return result;};
 document.addEventListener('click',async e=>{const a=e.target.closest('a[href*="scrap-import-template.xlsx"]');if(!a)return;e.preventDefault();try{const response=await fetch(a.href);if(!response.ok)throw Error('template');const zip=await JSZip.loadAsync(await response.arrayBuffer());for(const name of Object.keys(zip.files)){if(name.endsWith('.xml')){const source=await zip.file(name).async('string');if(source.includes(legacy))zip.file(name,source.replaceAll(legacy,current));}}const blob=await zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=a.download||'下腳料匯入標準範本.xlsx';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{toast('exportFailed');}});
})();
